          const isThisMonth = sameMonth(iso, monthIso);
          const isToday = iso === today;
          const isDemoRange = iso >= demoMon && iso <= demoFri;
          const dayIdx = demoDayIndex(iso);
          const hasEvent = dayIdx >= 0 && EVENTS.some(
