              isToday={iso === today}
              showAddButton={showAdd}
              onDetail={onDetail}
              onAddDay={
                showAdd
                  ? () => onDay(demoIdx)
                  : undefined
              }
            />
          );
        })}
      </div>
    </div>
  );
}

