/* ── Forum layout ─────────────────────────────────────────────────────────── */
.forum-layout {
  display: grid;
  grid-template-columns: 240px minmax(0, 1fr);
  gap: 20px;
  align-items: start;
}
.forum-sidebar {
  position: sticky;
  top: 20px;
  display: flex;
  flex-direction: column;
  gap: 0;
  padding: 4px 0;
}
.forum-sidebar-heading {
  font-size: 14px;
  font-weight: 700;
  margin: 0 0 14px;
  color: var(--ink);
}
.forum-community-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.forum-community-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  background: none;
  border: none;
  border-radius: 8px;
  padding: 8px 10px;
  text-align: left;
  cursor: pointer;
  transition: background 0.1s;
}
.forum-community-item:hover {
  background: var(--bg);
}
.forum-community-item.active {
  background: var(--mint);
  color: var(--green-dark);
}
.forum-community-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--green);
  color: white;
  font-size: 13px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex: none;
}
.forum-community-info {
  display: flex;
  flex-direction: column;
  min-width: 0;
  flex: 1;
}
.forum-community-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--ink);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.forum-community-cat {
  font-size: 11px;
  color: var(--muted);
}
.forum-joined-badge {
  font-size: 10px;
  background: var(--green);
  color: white;
  border-radius: 4px;
  padding: 2px 6px;
  flex: none;
}

/* Feed */
.forum-feed {
