+  overflow: hidden;
+  text-overflow: ellipsis;
+}
+.gcal-chip-cancelled {
+  background: #f8e9e3;
+  color: #9c4938;
+}
+.gcal-month-more {
+  font-size: 9px;
+  color: var(--muted);
+  padding-left: 4px;
+}
+
+/* ── Year view ────────────────────────────────────────────────────────────── */
+.gcal-year {
+  display: grid;
+  grid-template-columns: repeat(4, minmax(0, 1fr));
+  gap: 20px;
+  padding: 16px;
+}
+.gcal-mini-month {
+  display: flex;
+  flex-direction: column;
+  gap: 4px;
+}
+.gcal-mini-month-title {
+  font-size: 12px;
+  font-weight: 700;
+  color: var(--ink);
+  margin-bottom: 4px;
+}
+.gcal-mini-header {
+  display: grid;
+  grid-template-columns: repeat(7, 1fr);
+  gap: 1px;
+  margin-bottom: 2px;
+}
+.gcal-mini-dow {
+  font-size: 8px;
+  color: var(--muted);
+  text-align: center;
+  font-weight: 600;
+}
+.gcal-mini-grid {
+  display: grid;
+  grid-template-columns: repeat(7, 1fr);
+  gap: 1px;
+}
+.gcal-mini-cell {
+  position: relative;
+  font-size: 9px;
+  text-align: center;
+  padding: 2px 0;
+  border-radius: 3px;
+  background: none;
+  border: 0;
+  color: var(--ink);
+  cursor: pointer;
+  line-height: 1.5;
+}
+.gcal-mini-cell:hover {
+  background: var(--mint);
+}
+.gcal-mini-cell:focus-visible {
+  outline: 2px solid #57a77a;
+  outline-offset: 1px;
+}
+.gcal-mini-other {
+  color: var(--muted);
+  opacity: 0.5;
+}
+.gcal-mini-today {
+  background: var(--green);
+  color: white;
+  border-radius: 50%;
+}
+.gcal-mini-demo {
+  background: #f1f9f2;
+}
+.gcal-event-dot {
+  display: block;
+  width: 4px;
+  height: 4px;
+  border-radius: 50%;
+  background: var(--green);
+  margin: 0 auto;
+}
+
+/* ── Responsive ───────────────────────────────────────────────────────────── */
+@media (max-width: 960px) {
+  .gcal-year {
+    grid-template-columns: repeat(3, minmax(0, 1fr));
+  }
+}
+@media (max-width: 760px) {
+  .gcal-toolbar {
+    flex-direction: column;
+    align-items: flex-start;
+  }
+  .gcal-toolbar-right {
+    flex-wrap: wrap;
+    gap: 8px;
+  }
+  .gcal-year {
+    grid-template-columns: repeat(2, minmax(0, 1fr));
+    padding: 10px;
+    gap: 14px;
+  }
+  .gcal-time-grid-wrap {
+    overflow-x: auto;
+  }
+  .gcal-time-grid {
+    min-width: 500px;
+  }
+  .gcal-month-cell {
+    min-height: 58px;
+  }
+  .gcal-title {
+    font-size: 13px;
+  }
+}

