              showAddButton={showAdd}
              onDetail={onDetail}
              onAddDay={
                showAdd
                  ? () => onDay(demoIdx)
                  : undefined
              }
            />
          );
        })}
      </div>
    </div>
  );
}

/** Day view header row */
function DayHeader({ iso, today }: { iso: string; today: string }) {
