  margin: 5px 0;
}
.chat-event .row {
  margin-top: 12px;
  flex-wrap: wrap;
}
.event-problem {
  color: #97412e;
  font-size: 13px;
  line-height: 1.5;
}
.planner-calendar {
  align-self: start;
  height: 720px;
  display: flex;
  flex-direction: column;
}
.planner-calendar .section-bar {
  margin-bottom: 0;
}
.calendar-legend {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  font-size: 11px;
  color: var(--green-dark);
  margin: 8px 0;
}
.planner-agenda {
  overflow: auto;
  min-height: 0;
  padding-right: 4px;
}
.agenda-day {
  padding: 12px 0;
  border-top: 1px solid var(--line);
}
.agenda-day h3 {
  display: flex;
  justify-content: space-between;
  margin: 0 0 10px;
  font-size: 13px;
}
.agenda-day h3 span {
  font-weight: 400;
  color: var(--muted);
}
.agenda-entry {
  display: grid;
  gap: 4px;
  text-align: left;
  width: 100%;
  border: 0;
  border-radius: 9px;
  padding: 11px 12px;
  margin-top: 8px;
  font-size: 12px;
  line-height: 1.45;
}
.agenda-entry strong {
  font-weight: 600;
}
.agenda-entry span,
.agenda-entry small {
  font-size: 11px;
}
.agenda-entry.commitment {
  background: var(--bg);
  color: var(--muted);
}
.agenda-entry.chosen {
  background: var(--mint);
  color: var(--green-dark);
  cursor: pointer;
}
.agenda-entry.cancelled {
  background: #fff0e8;
  color: #97412e;
}
/* Retained for RsvpDialog which still uses <dialog> */
.rsvp-dialog {
