      {/* Calendar body */}
      {(view === "day" || view === "week") && (
        <div className="gcal-body panel">
          <TimeGrid
            dates={viewDates}
            state={state}
            today={today}
            onDetail={onDetail}
            onDay={onDay}
          />
        </div>
      )}

      {view === "month" && (
        <div className="gcal-body panel">
          {!isShowingDemoWeek() && (
            <DemoWeekBanner onGoToDemo={goToDemoWeek} />
          )}
          <MonthView
            anchor={monthStart(anchor)}
            state={state}
            today={today}
            onDayClick={handleDayClick}
          />
        </div>
      )}

      {view === "year" && (
        <div className="gcal-body panel">
          {!isShowingDemoWeek() && (
            <DemoWeekBanner onGoToDemo={goToDemoWeek} />
          )}
          <YearView
            anchor={anchor}
            state={state}
            today={today}
            onDayClick={handleDayClick}
          />
        </div>
      )}
    </div>
  );
}

