.gcal-chip-cancelled {
  background: #f8e9e3;
  color: #9c4938;
}
.gcal-month-more {
  font-size: 9px;
  color: var(--muted);
  padding-left: 4px;
}

/* ── Year view ────────────────────────────────────────────────────────────── */
.gcal-year {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 20px;
  padding: 16px;
}
.gcal-mini-month {
  display: flex;
  flex-direction: column;
  gap: 4px;
