    gap: 6px;
  }
  .gcal-year {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    padding: 10px;
    gap: 14px;
  }
  .gcal-month-cell {
    min-height: 58px;
  }
  .gcal-title {
    font-size: 13px;
  }
}

