}
.forum-create-tags-row {
  display: flex;
  gap: 8px;
}
.forum-tag-btn {
  border: 1px solid var(--line);
  border-radius: 20px;
  background: white;
  padding: 5px 14px;
  font-size: 12px;
  color: var(--muted);
  cursor: pointer;
}
.forum-tag-btn:hover {
  background: var(--bg);
  border-color: var(--green);
  color: var(--green-dark);
}
.forum-create-body {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: white;
  padding: 12px;
  font-size: 14px;
  color: var(--ink);
  resize: vertical;
  min-height: 160px;
  outline: none;
