}
.reason {
  font-size: 10px;
  line-height: 1.6;
  color: #527357;
  padding-top: 10px;
  margin-top: auto;
  margin-bottom: 11px;
}
.reason.blocked {
  color: var(--notice-ink);
}
.event-body .btn.blocked {
