  display: block;
  margin: 0 auto 12px;
}
.planner-teaser h2 {
  font-size: 19px;
}
.planner-teaser p {
  font-size: 11px;
  color: var(--muted);
  margin: 9px 0 16px;
}
.planner-teaser .btn {
  width: 100%;
}
.label {
  font-size: 9px;
  letter-spacing: 0.5px;
  color: var(--muted);
  display: inline-block;
  margin-top: 12px;
}
.feed {
  border-bottom: 1px solid var(--line);
  padding: 13px 0;
}
.feed:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}
.feed strong {
  font-size: 11px;
  font-weight: 600;
  line-height: 1.5;
}
.feed p {
  font-size: 10px;
  color: var(--muted);
  margin: 4px 0 0;
}
.feed .text-btn {
  font-size: 10px;
  margin-top: 6px;
  padding-left: 0;
}
.group {
  display: flex;
  gap: 10px;
  align-items: center;
  padding: 10px 0;
}
.group-icon {
  width: 32px;
  height: 32px;
  border-radius: 9px;
