  place-items: center;
  background: #eff1e7;
  color: #6c7b52;
}
.group strong {
  font-size: 11px;
}
.group small {
  display: block;
  font-size: 9px;
  color: var(--muted);
  margin-top: 3px;
}
.section-footer {
  font-size: 10px;
  color: var(--muted);
  margin-top: 25px;
  display: flex;
  justify-content: space-between;
  gap: 12px;
}
.planner-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: 22px;
}
.chat-panel {
  display: flex;
  flex-direction: column;
  min-height: 620px;
}
.chat-header {
  display: flex;
  gap: 12px;
  align-items: center;
  padding-bottom: 17px;
  border-bottom: 1px solid var(--line);
}
.chat-header img {
  width: 45px;
  height: 45px;
  object-fit: contain;
}
.chat-header h2 {
  font-size: 15px;
}
.status-label {
  font-size: 10px;
  color: var(--muted);
  margin-top: 4px;
