  gap: 10px;
  align-items: flex-start;
}
.message img {
  width: 30px;
  height: 32px;
  object-fit: contain;
}
.bubble {
  background: var(--bg);
  border-radius: 0 12px 12px 12px;
  padding: 14px 16px;
  font-size: 12px;
  line-height: 1.7;
  max-width: 90%;
  white-space: pre-line;
}
.message.user-msg {
  justify-content: flex-end;
}
.user-msg .bubble {
  background: var(--mint);
  border-radius: 12px 0 12px 12px;
  color: var(--green-dark);
}
.prompts {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-bottom: 15px;
}
.prompts button {
  font-size: 10px;
  background: white;
  border: 1px solid var(--line);
  border-radius: 7px;
  padding: 8px 10px;
  text-align: left;
}
.prompts button:hover {
  border-color: var(--green);
