/* Planner actions and calendar share the same live schedule. */
.chat-event-list {
  white-space: normal;
  display: grid;
  gap: 12px;
  margin-top: 16px;
}
.chat-event {
  background: var(--white, #fff);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 14px;
}
.chat-event h3 {
  font-size: 15px;
  margin: 8px 0;
  line-height: 1.4;
}
.chat-event .meta {
  margin: 5px 0;
}
.chat-event .row {
  margin-top: 12px;
  flex-wrap: wrap;
}
.event-problem {
  color: #97412e;
  font-size: 13px;
  line-height: 1.5;
}
.planner-calendar {
  align-self: start;
  height: 720px;
  display: flex;
  flex-direction: column;
}
.planner-calendar .section-bar {
  margin-bottom: 0;
}
.calendar-legend {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  font-size: 11px;
  color: var(--green-dark);
  margin: 8px 0;
}
.planner-agenda {
  overflow: auto;
  min-height: 0;
  padding-right: 4px;
}
.agenda-day {
  padding: 12px 0;
  border-top: 1px solid var(--line);
}
.agenda-day h3 {
  display: flex;
  justify-content: space-between;
  margin: 0 0 10px;
  font-size: 13px;
}
.agenda-day h3 span {
  font-weight: 400;
  color: var(--muted);
}
.agenda-entry {
  display: grid;
  gap: 4px;
  text-align: left;
  width: 100%;
  border: 0;
  border-radius: 9px;
  padding: 11px 12px;
  margin-top: 8px;
  font-size: 12px;
  line-height: 1.45;
}
.agenda-entry strong {
  font-weight: 600;
}
.agenda-entry span,
.agenda-entry small {
  font-size: 11px;
}
.agenda-entry.commitment {
  background: var(--bg);
  color: var(--muted);
}
.agenda-entry.chosen {
  background: var(--mint);
  color: var(--green-dark);
  cursor: pointer;
}
.agenda-entry.cancelled {
  background: #fff0e8;
  color: #97412e;
}
/* Retained for RsvpDialog which still uses <dialog> */
.rsvp-dialog {
  border: 0;
  border-radius: 16px;
  box-shadow: var(--shadow);
  padding: 28px;
  max-width: 530px;
  width: calc(100% - 30px);
  color: var(--ink);
  max-height: 90dvh;
  overflow-y: auto;
}
.rsvp-dialog::backdrop {
  background: #15291f65;
}
.rsvp-dialog h3 {
  margin: 18px 0 10px;
}
.rsvp-name {
  display: grid;
  gap: 8px;
  margin: 20px 0;
  font-size: 14px;
  font-weight: 600;
}
.rsvp-name input {
  width: 100%;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  font: inherit;
}
.rsvp-check {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 14px;
  line-height: 1.5;
}
.rsvp-check input {
  width: 18px;
  height: 18px;
  flex: 0 0 auto;
  margin-top: 2px;
  accent-color: var(--green-dark);
}
.rsvp-dialog .row {
  flex-wrap: wrap;
  margin-top: 22px;
}
@media (max-width: 1000px) {
  .planner-calendar {
    height: auto;
    max-height: 650px;
  }
}

.why-fits { margin:10px 0 0; font-size:13px; line-height:1.5; }
.evidence-more { margin-top:10px; font-size:12px; }
.evidence-more summary { cursor:pointer; color:var(--green); font-weight:650; width:fit-content; }
.evidence-more[open] summary { margin-bottom:4px; }
.evidence { margin:12px 0; font-size:12px; line-height:1.6; }
.evidence div { margin-bottom:8px; }
.evidence dt { font-weight:700; }
.evidence dd { margin:0; overflow-wrap:anywhere; }
.briefing { margin:18px 0; }
.briefing-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:18px; }
.briefing-grid > * { min-width:0; overflow-wrap:anywhere; }
.briefing ul { padding-left:18px; }
.communities { margin-bottom:24px; }
.communities article { padding:16px; border:1px solid #e1e7de; border-radius:12px; }
.search:focus-within,.composer:focus-within { outline:3px solid #57a77a; outline-offset:3px; }
@media(max-width:700px) { .briefing-grid { grid-template-columns:minmax(0,1fr); } .row { flex-wrap:wrap; } .text-btn { white-space:normal; text-align:left; } }
.demo-launcher { margin-bottom:20px; }
.demo-launcher ol { padding-left:20px; line-height:1.7; }
.review-record { border-top:1px solid #e1e7de; padding:12px 0; overflow-wrap:anywhere; }
.demo-launcher .row { display:flex; flex-wrap:wrap; gap:8px; }

/* ── Forum layout ─────────────────────────────────────────────────────────── */
.forum-layout {
  display: grid;
  grid-template-columns: 240px minmax(0, 1fr);
  gap: 20px;
  align-items: start;
}
.forum-sidebar {
  position: sticky;
  top: 20px;
  display: flex;
  flex-direction: column;
  gap: 0;
  padding: 4px 0;
}
.forum-sidebar-heading {
  font-size: 14px;
  font-weight: 700;
  margin: 0 0 14px;
  color: var(--ink);
}
.forum-community-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.forum-community-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  background: none;
  border: none;
  border-radius: 8px;
  padding: 8px 10px;
  text-align: left;
  cursor: pointer;
  transition: background 0.1s;
}
.forum-community-item:hover {
  background: var(--bg);
}
.forum-community-item.active {
  background: var(--mint);
  color: var(--green-dark);
}
.forum-community-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--green);
  color: white;
  font-size: 13px;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex: none;
}
.forum-community-info {
  display: flex;
  flex-direction: column;
  min-width: 0;
  flex: 1;
}
.forum-community-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--ink);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.forum-community-cat {
  font-size: 11px;
  color: var(--muted);
}
.forum-joined-badge {
  font-size: 10px;
  background: var(--green);
  color: white;
  border-radius: 4px;
  padding: 2px 6px;
  flex: none;
}

/* Feed */
.forum-feed {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.forum-feed-header {
  display: flex;
  align-items: center;
  gap: 16px;
}
.forum-feed-title {
  font-size: 18px;
  font-weight: 700;
  margin: 0;
  white-space: nowrap;
}
.forum-search-field {
  flex: 1;
  font-size: 12px;
  color: var(--muted);
  gap: 0;
}
.forum-search-field input {
  width: 100%;
}

/* New post composer */
.forum-new-post {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 0 0 16px;
  border-bottom: 1px solid var(--line);
  margin-bottom: 4px;
}
.forum-new-post-row {
  display: flex;
  align-items: center;
  gap: 12px;
}
.forum-create-trigger {
  flex: 1;
  border: 1px solid var(--line);
  border-radius: 20px;
  background: var(--bg);
  padding: 9px 16px;
  color: var(--muted);
  text-align: left;
  font-size: 13px;
  transition: background 0.15s, border-color 0.15s;
}
.forum-create-trigger:hover {
  background: var(--mint);
  border-color: var(--green);
  color: var(--green-dark);
}

/* Post card */
.forum-post-card {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 16px 0;
  border-bottom: 1px solid var(--line);
}
.forum-post-card:last-child {
  border-bottom: none;
}
.forum-post-card-meta {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 11px;
}
.forum-post-community {
  font-weight: 700;
  font-size: 11px;
  color: var(--green-dark);
  background: var(--mint);
  padding: 2px 8px;
  border-radius: 4px;
}
.forum-post-author {
  color: var(--muted);
  font-size: 11px;
}
.forum-post-time {
  color: var(--muted);
  font-size: 11px;
}
.forum-post-title {
  font-size: 16px;
  font-weight: 700;
  color: var(--ink);
  text-align: left;
  white-space: normal;
  line-height: 1.35;
}
.forum-post-title:hover {
  color: var(--green);
}
.forum-post-preview {
  font-size: 13px;
  color: var(--muted);
  margin: 2px 0 0;
  line-height: 1.5;
}
.forum-post-footer {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-top: 6px;
}
.forum-stat {
  font-size: 12px;
  color: var(--muted);
  font-weight: 600;
  background: none;
  border: none;
  padding: 0;
}
.forum-stat.text-btn {
  cursor: pointer;
}
.forum-stat.text-btn:hover {
  color: var(--green);
}
.forum-like-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 12px;
  font-weight: 700;
  color: var(--muted);
  background: none;
  border: 1px solid transparent;
  border-radius: 20px;
  padding: 3px 10px;
  cursor: pointer;
  transition: color 0.15s, background 0.15s, border-color 0.15s;
}
.forum-like-btn:hover {
  color: var(--green);
  background: var(--mint);
  border-color: var(--green);
}
.forum-like-btn.liked {
  color: var(--green-dark);
  background: var(--mint);
  border-color: var(--green);
}
.forum-comment-like {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 11px;
  font-weight: 600;
  color: var(--muted);
  background: none;
  border: none;
  padding: 2px 0;
  margin-top: 4px;
  cursor: pointer;
  transition: color 0.15s;
}
.forum-comment-like:hover {
  color: var(--green);
}
.forum-comment-like.liked {
  color: var(--green-dark);
}
.forum-empty {
  color: var(--muted);
  font-size: 13px;
  padding: 24px 0;
  text-align: center;
}

/* Post detail sub-page */
.forum-detail-page {
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.forum-back-btn {
  font-size: 13px;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 4px;
}
.forum-detail-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 260px;
  gap: 20px;
  align-items: start;
}
.forum-detail-article {
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.forum-detail-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.forum-detail-title {
  font-size: 22px;
  font-weight: 800;
  margin: 0;
  line-height: 1.3;
}
.forum-detail-body {
  font-size: 14px;
  line-height: 1.7;
  color: var(--ink);
  margin: 0;
}
.forum-post-stats {
  display: flex;
  gap: 18px;
  align-items: center;
  padding: 12px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  flex-wrap: wrap;
}
.forum-comments {
  display: flex;
  flex-direction: column;
  gap: 14px;
  margin-top: 4px;
}
.forum-comments-heading {
  font-size: 14px;
  font-weight: 700;
  margin: 0;
}
.forum-comment {
  display: flex;
  gap: 10px;
  align-items: flex-start;
}
.avatar-sm {
  width: 28px;
  height: 28px;
  font-size: 12px;
  flex: none;
}
.forum-comment-author {
  font-size: 12px;
  font-weight: 700;
  color: var(--ink);
}
.forum-comment-text {
  font-size: 13px;
  color: var(--ink);
  margin: 4px 0 0;
  line-height: 1.5;
}
.forum-empty-comments {
  font-size: 13px;
  color: var(--muted);
}
.forum-comment-form {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding-top: 10px;
  border-top: 1px solid var(--line);
  margin-top: 6px;
}
.forum-detail-sidebar {
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.forum-sidebar-desc {
  font-size: 13px;
  color: var(--muted);
  margin: 0;
  line-height: 1.5;
}

/* Responsive */
@media (max-width: 860px) {
  .forum-layout {
    grid-template-columns: minmax(0, 1fr);
  }
  .forum-sidebar {
    position: static;
  }
  .forum-detail-layout {
    grid-template-columns: minmax(0, 1fr);
  }
}

/* ── Create post page ─────────────────────────────────────────────────────── */
.forum-create-page {
