/* ═══════════════════════════════════════════════════════════════════════════
   Google-Calendar-style CalendarView (My Calendar page only)
   ═══════════════════════════════════════════════════════════════════════════ */

/* Root wrapper */
.gcal-root {
  display: flex;
  flex-direction: column;
  gap: 0;
  margin-bottom: 28px;
}

/* ── Toolbar ──────────────────────────────────────────────────────────────── */
/*
 * Fix #8: at ≥ 1024 px the toolbar-right uses a 2-row sub-layout so the
 * switcher always sits in the top row and doesn't jump when the title
 * changes length.  On smaller screens everything wraps as before.
 */
.gcal-toolbar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 10px;
}
.gcal-toolbar-left {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  flex: 1;
  min-width: 0;
}
.gcal-toolbar-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
  flex: none;
}
.gcal-toolbar-right-top {
  display: flex;
  align-items: center;
  gap: 8px;
}
.gcal-toolbar-right-bottom {
  display: flex;
  align-items: center;
  gap: 8px;
}
.gcal-today-btn {
  font-size: 12px;
  flex: none;
}
.gcal-nav-btn {
  border: 1px solid var(--line);
  background: white;
  border-radius: 7px;
  width: 30px;
  height: 30px;
  font-size: 16px;
  display: inline-grid;
  place-items: center;
  line-height: 1;
  flex: none;
}
.gcal-nav-btn:hover {
  background: var(--mint);
}
.gcal-title {
  font-size: 15px;
  font-weight: 650;
  color: var(--ink);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* View switcher */
.gcal-view-switcher {
  display: flex;
  border: 1px solid var(--line);
  border-radius: 8px;
  overflow: hidden;
}
.gcal-switch-btn {
  background: white;
  border: 0;
  border-left: 1px solid var(--line);
  padding: 6px 11px;
  font-size: 12px;
  font-weight: 600;
  color: var(--muted);
}
.gcal-switch-btn:first-child {
  border-left: 0;
}
.gcal-switch-btn:hover {
  background: var(--bg);
  color: var(--ink);
}
.gcal-switch-btn.active,
.gcal-switch-btn[aria-pressed="true"] {
  background: var(--mint);
  color: var(--green);
}
.gcal-switch-btn:focus-visible {
  outline: 3px solid #57a77a;
  outline-offset: -2px;
  z-index: 1;
  position: relative;
}

/* Legend sits just below toolbar */
.gcal-legend {
  margin-bottom: 8px;
  margin-top: 0;
}

/* Demo banner */
.gcal-demo-banner {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--notice-bg);
  color: var(--notice-ink);
  border-radius: 9px;
  padding: 10px 14px;
  font-size: 12px;
  margin-bottom: 10px;
  flex-wrap: wrap;
}

/* ── Body (panel) ─────────────────────────────────────────────────────────── */
.gcal-body {
  padding: 0;
  overflow: hidden;
}

/*
 * .gcal-scroll-host — horizontal scroll for phones (overflow-x: auto).
 *
 * The header and body are BOTH inside .gcal-time-grid-wrap (vertical scroll,
 * scrollbar-gutter: stable).  Because they share the same containing block
 * the scrollbar lane is counted identically for header and day columns, so
 * there is no drift at any desktop or phone width.
 */
.gcal-scroll-host {
  overflow-x: auto;
}

/* ── Column headers (Day/Week) ────────────────────────────────────────────── */
.gcal-col-headers {
  display: flex;
  border-bottom: 1px solid var(--line);
  background: white;
  position: sticky;
  top: 0;
  z-index: 5;
  /* min-width inherited from parent .gcal-time-grid-wrap / .gcal-time-grid */
}
.gcal-gutter {
  width: 56px;
  flex: none;
}
.gcal-col-head {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 6px 4px;
  gap: 2px;
  min-width: 0;
}
.gcal-dow {
  font-size: 10px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
/*
 * Issue 2: give .gcal-dom a fixed height so the today-circle (32 px) does
 * not make Monday's column taller than the others — all "+" buttons stay on
 * one row.
 */
.gcal-dom {
  font-size: 20px;
  font-weight: 600;
  color: var(--ink);
  line-height: 1;
  min-width: 32px;
  height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-align: center;
}
.gcal-today-head .gcal-dow {
  color: var(--green);
}
.gcal-today-dot {
  background: var(--green);
  color: white !important;
  border-radius: 999px;
  min-width: 32px;
  height: 32px;
  display: inline-grid;
  place-items: center;
}

/* Fix #4: "+" button in the column header */
.gcal-add-header-btn {
  border: 1px dashed #b5c9b2;
  background: none;
  color: var(--green);
  border-radius: 50%;
  width: 20px;
  height: 20px;
  display: inline-grid;
  place-items: center;
  margin-top: 2px;
  flex: none;
}
.gcal-add-header-btn .icon {
  width: 12px;
  height: 12px;
}
.gcal-add-header-btn:hover {
  background: var(--mint);
}
.gcal-add-header-btn:focus-visible {
  outline: 2px solid #57a77a;
  outline-offset: 2px;
}

/* ── Time grid ────────────────────────────────────────────────────────────── */
/*
 * .gcal-time-grid-wrap contains BOTH the sticky header and the day columns.
 * scrollbar-gutter:stable reserves the scrollbar lane for BOTH, so their
 * widths are always identical — no drift at any viewport width.
 * overflow-x is visible so .gcal-scroll-host handles horizontal scrolling.
 */
.gcal-time-grid-wrap {
  overflow-y: auto;
  overflow-x: visible;
  max-height: 580px;
  scrollbar-gutter: stable;
}
.gcal-time-grid {
  display: flex;
  position: relative;
  min-width: 500px;
}
/* Gutter with hour labels */
.gcal-gutter {
  display: flex;
  flex-direction: column;
  width: 56px;
  flex: none;
  border-right: 1px solid var(--line);
  background: white;
  position: sticky;
  left: 0;
  z-index: 4;
}
.gcal-hour-label {
  font-size: 9px;
  color: var(--muted);
  padding: 0 6px;
  text-align: right;
  height: 48px;
  display: flex;
  align-items: flex-start;
  padding-top: 2px;
  box-sizing: border-box;
}
/* Grid lines */
.gcal-grid-lines {
  position: absolute;
  left: 56px;
  right: 0;
  top: 0;
  bottom: 0;
  display: flex;
  flex-direction: column;
  pointer-events: none;
  z-index: 1;
}
.gcal-grid-line {
  height: 48px;
  border-top: 1px solid var(--line);
}
/* Day columns */
.gcal-day-col {
  flex: 1;
  position: relative;
  height: calc(13 * 48px); /* 13 hours × 48px each */
  border-left: 1px solid var(--line);
  min-width: 0;
}
.gcal-day-col:first-of-type {
  border-left: 0;
}

/* ── Event blocks (positioned) ────────────────────────────────────────────── */
/*
 * Fix #6: chosen events use a solid green left border to stand out clearly
 *   from the plain grey classes.
 * Fix #7: title wraps up to 2 lines; title attribute shows full text on hover.
 */
.gcal-event-block {
  position: absolute;
  border-radius: 5px;
  padding: 3px 5px 3px 7px;
  font-size: 10px;
  line-height: 1.35;
  overflow: hidden;
  z-index: 2;
  border: 0;
  text-align: left;
  min-height: 22px;
  display: flex;
  flex-direction: column;
  cursor: pointer;
}
/* Fix #7: allow title to wrap up to 2 lines */
.gcal-event-block strong {
  font-size: 10px;
  font-weight: 600;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: normal;
  line-height: 1.3;
}
.gcal-event-block span {
  font-size: 9px;
  opacity: 0.85;
  white-space: nowrap;
}
/* Classes: plain grey */
.gcal-class {
  background: #f0f1ec;
  color: var(--ink);
  border-left: 3px solid #c4c9bf;
}
/* Fix #6: chosen events: stronger green with solid left border */
.gcal-chosen {
  background: #d4eed7;
  color: var(--green-dark);
  border-left: 3px solid var(--green);
}
.gcal-cancelled {
  background: #f8e9e3 !important;
  color: #9c4938 !important;
  border-left: 3px solid #d9847a !important;
}
.gcal-event-block:focus-visible {
  outline: 3px solid #57a77a;
  outline-offset: 2px;
  z-index: 10;
}

/* "Now" line */
.gcal-now-line {
  position: absolute;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--green);
  z-index: 3;
  pointer-events: none;
}
.gcal-now-line::before {
  content: "";
  position: absolute;
  left: -4px;
  top: -4px;
  width: 10px;
  height: 10px;
  background: var(--green);
  border-radius: 50%;
}

/* ── Month view ───────────────────────────────────────────────────────────── */
/*
 * Fix #1: both header and grid use repeat(7, minmax(0,1fr)) so every column
 * is equal width and day numbers always sit under the correct weekday header.
 * Fix #5: chips use white-space:nowrap + overflow:hidden + text-overflow:ellipsis.
 */
.gcal-month {
  padding: 12px;
}
.gcal-month-header {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 2px;
  margin-bottom: 4px;
}
.gcal-month-dow {
  font-size: 10px;
  color: var(--muted);
  text-align: center;
  padding: 4px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}
.gcal-month-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 2px;
}
.gcal-month-cell {
  min-height: 80px;
  border: 1px solid var(--line);
  border-radius: 7px;
  padding: 4px 5px;
  background: white;
  text-align: left;
  display: flex;
  flex-direction: column;
  gap: 2px;
  font-size: 10px;
  cursor: pointer;
  min-width: 0;
  overflow: hidden;
}
.gcal-month-cell:hover {
  background: var(--bg);
}
.gcal-month-cell:focus-visible {
  outline: 3px solid #57a77a;
  outline-offset: 2px;
}
.gcal-other-month {
  background: #fafafa;
  opacity: 0.55;
}
.gcal-today-cell {
  border-color: var(--green);
}
.gcal-demo-week-cell {
  background: #f1f9f2;
}
.gcal-month-day-num {
  font-size: 13px;
  font-weight: 600;
  color: var(--ink);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  flex: none;
  /* Fix #3 (month): today dot wins over demo-week background */
}
/* Fix #3: today dot in month view — more specific than .gcal-demo-week-cell .gcal-month-day-num */
.gcal-today-cell .gcal-today-dot,
.gcal-month-day-num.gcal-today-dot {
  background: var(--green);
  color: white !important;
}
.gcal-demo-week-label {
  font-size: 8px;
  color: var(--green);
  font-weight: 600;
  letter-spacing: 0.3px;
  background: var(--mint);
  border-radius: 3px;
  padding: 1px 4px;
  align-self: flex-start;
  white-space: nowrap;
}
/* Fix #1 + #5: chips are single-line with ellipsis; no content can widen the cell */
.gcal-month-chip {
  display: block;
  background: #d4eed7;
  color: var(--green-dark);
  border-radius: 3px;
  padding: 1px 4px;
  font-size: 9px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
}
.gcal-chip-cancelled {
  background: #f8e9e3;
  color: #9c4938;
}
.gcal-month-more {
  font-size: 9px;
  color: var(--muted);
  padding-left: 4px;
}

/* ── Year view ────────────────────────────────────────────────────────────── */
.gcal-year {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 20px;
  padding: 16px;
}
.gcal-mini-month {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.gcal-mini-month-title {
  font-size: 12px;
  font-weight: 700;
  color: var(--ink);
  margin-bottom: 4px;
}
.gcal-mini-header {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 1px;
  margin-bottom: 2px;
}
.gcal-mini-dow {
  font-size: 8px;
  color: var(--muted);
  text-align: center;
  font-weight: 600;
}
.gcal-mini-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 1px;
}
.gcal-mini-cell {
  position: relative;
  font-size: 9px;
  text-align: center;
  padding: 2px 0;
  border-radius: 3px;
  background: none;
  border: 0;
  color: var(--ink);
  cursor: pointer;
  line-height: 1.5;
}
.gcal-mini-cell:hover {
  background: var(--mint);
}
.gcal-mini-cell:focus-visible {
  outline: 2px solid #57a77a;
  outline-offset: 1px;
}
.gcal-mini-other {
  color: var(--muted);
  opacity: 0.5;
}
/* Fix #3: demo-week background (applied before today so today wins) */
.gcal-mini-demo {
  background: #f1f9f2;
}
/* Fix #3: today circle always dark green + white text, even on demo-week days */
.gcal-mini-today {
  background: var(--green) !important;
  color: white !important;
  border-radius: 50%;
}
.gcal-event-dot {
  display: block;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--green);
  margin: 0 auto;
}

/* ── Responsive ───────────────────────────────────────────────────────────── */
@media (max-width: 960px) {
  .gcal-year {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}
/* Fix #8: at < 760 px allow the toolbar to stack */
@media (max-width: 760px) {
  .gcal-toolbar {
    flex-direction: column;
    align-items: flex-start;
  }
  .gcal-toolbar-right {
    align-items: flex-start;
    width: 100%;
  }
  .gcal-toolbar-right-top,
  .gcal-toolbar-right-bottom {
    flex-wrap: wrap;
    gap: 6px;
  }
  .gcal-year {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    padding: 10px;
    gap: 14px;
  }
  .gcal-month-cell {
    min-height: 58px;
  }
  .gcal-title {
    font-size: 13px;
  }
}

