  place-items: center;
  background: #eff1e7;
  color: #6c7b52;
}
.group strong {
  font-size: 11px;
}
.group small {
  display: block;
  font-size: 9px;
  color: var(--muted);
  margin-top: 3px;
}
.section-footer {
  font-size: 10px;
  color: var(--muted);
  margin-top: 25px;
  display: flex;
  justify-content: space-between;
  gap: 12px;
}
.planner-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: 22px;
}
.chat-panel {
  display: flex;
  flex-direction: column;
