  flex: 1;
  min-width: 0;
  padding: 5px;
  font-size: 12px;
  line-height: 1.5;
  outline: none;
  height: 46px;
  max-height: 130px;
}
.composer button {
  background: var(--green);
  color: white;
  border: 0;
  border-radius: 7px;
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
}
.fineprint {
  font-size: 9px;
  line-height: 1.5;
  color: var(--muted);
  margin: 9px 0 0;
  text-align: center;
}
.draft-item {
  padding: 15px 0;
  border-bottom: 1px solid var(--line);
}
.draft-item:last-child {
  border: 0;
}
.draft-item h3 {
  font-size: 12px;
}
.draft-item .meta {
  font-size: 10px;
}
.draft-item .reason {
  margin-bottom: 8px;
}
.draft-item .btn {
  width: 100%;
}
.empty {
  text-align: center;
  padding: 40px 20px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.7;
}
.empty .icon {
  display: block;
  margin: 0 auto 15px;
  width: 30px;
  height: 30px;
  color: #9fb39e;
}
.empty h3 {
  color: var(--ink);
  margin-bottom: 8px;
}
.summary-line {
  display: flex;
  justify-content: space-between;
  padding: 10px 0;
  font-size: 11px;
  border-bottom: 1px solid var(--line);
}
.summary-line:last-child {
  border: 0;
}
.notice {
  border-radius: 9px;
  background: var(--notice-bg);
  color: var(--notice-ink);
  padding: 13px 15px;
  font-size: 11px;
  line-height: 1.6;
  margin-bottom: 18px;
}
.notice .btn {
  margin-top: 9px;
}
.calendar-full .week {
  gap: 13px;
}
.calendar-full .calendar-item {
  font-size: 12px;
  min-height: 90px;
  padding: 15px;
}
.calendar-full .calendar-item strong {
  font-size: 12px;
}
.calendar-full .calendar-item span {
  font-size: 11px;
}
.calendar-full .week-day {
  min-height: 330px;
}
.calendar-full .day-head {
  padding-bottom: 20px;
}
.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}
.field {
  display: flex;
  flex-direction: column;
  gap: 7px;
  font-size: 12px;
  color: var(--muted);
}
.field input,
.field select,
.field textarea {
  border: 1px solid var(--line);
  border-radius: 7px;
  background: white;
  padding: 11px;
  color: var(--ink);
  width: 100%;
}
.field textarea {
  min-height: 90px;
}
.field.full {
  grid-column: 1/-1;
}
.row {
  display: flex;
  gap: 10px;
  align-items: center;
  flex-wrap: wrap;
}
.block-row {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  align-items: center;
  padding: 13px 0;
  border-bottom: 1px solid var(--line);
  font-size: 12px;
}
.block-row small {
  display: block;
  color: var(--muted);
  margin-top: 5px;
}
.wide-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr);
  gap: 24px;
}
.topic-options {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin: 16px 0;
}
.topic-options label {
  font-size: 12px;
  background: var(--bg);
  padding: 10px;
  border-radius: 7px;
}
.topic-options input {
  accent-color: var(--green);
  margin-right: 7px;
}
.discussion {
  padding: 20px 0;
  border-bottom: 1px solid var(--line);
  display: flex;
  gap: 15px;
}
.discussion p {
  font-size: 12px;
  margin: 8px 0;
  color: var(--muted);
}
.discussion .avatar {
