  gap: 12px;
  margin-top: 16px;
}
.chat-event {
  background: var(--white, #fff);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 14px;
}
.chat-event h3 {
  font-size: 15px;
  margin: 8px 0;
  line-height: 1.4;
}
.chat-event .meta {
  margin: 5px 0;
}
.chat-event .row {
  margin-top: 12px;
  flex-wrap: wrap;
}
.event-problem {
  color: #97412e;
  font-size: 13px;
  line-height: 1.5;
}
.planner-calendar {
  align-self: start;
